"""Original supportive-care questions on symptoms and treatment complications."""
from qbank_authoring import question,ref
rows=[]
def q(*args,**kwargs):rows.append(question(*args,**kwargs))
PC=ref('ASCO palliative care guideline update 2024','https://doi.org/10.1200/JCO.24.00542')
OP=ref('ASCO opioids for cancer-related pain guideline','https://doi.org/10.1200/JCO.22.02198')
NV=ref('MASCC/ESMO antiemetic guideline update','https://pmc.ncbi.nlm.nih.gov/articles/PMC10937211/')

q('When should specialist palliative care be considered for a patient with advanced cancer receiving active anticancer treatment?', 'Early alongside oncology care, especially with significant symptom or psychosocial burden',[
 ('Only after all disease-directed treatment has stopped','Concurrent palliative and anticancer care is recommended.'),('Only during the final hours of life','Symptom and decision support can benefit patients much earlier.'),('Only if the patient chooses a do-not-resuscitate order','Palliative involvement is not conditional on that decision.')],
 'Palliative care can accompany disease-directed treatment','**Its focus includes symptoms, quality of life, communication and support.**',['It is not synonymous with abandoning active treatment.','Family and caregiver needs are also relevant.'],'**Integrate the team early in advanced disease.**',['Reassess physical, psychological and practical needs.','Explain the role clearly to reduce avoidable misconceptions.'],[['Oncology','Cancer-directed treatment'],['Palliative care','Symptoms and goals'],['Timing','Can be concurrent']],[PC])

q('A patient with severe cancer pain and advanced kidney impairment becomes increasingly drowsy on morphine. Which approach is most appropriate?', 'Assess opioid toxicity and other causes, reduce or rotate treatment as appropriate, and increase monitoring using renal-aware prescribing',[
 ('Escalate morphine automatically because drowsiness proves uncontrolled pain','Drowsiness can reflect accumulation and toxicity.'),('Assume renal function cannot affect opioid metabolites','Several opioid metabolites accumulate in kidney impairment.'),('Replace oral morphine with a high-dose fentanyl patch in an opioid-naive patient','Transdermal fentanyl is not an unrestricted starting option for opioid-naive patients.')],
 'Analgesia must account for clearance and clinical response','**Renal impairment can increase opioid and metabolite toxicity.**',['Sedation, myoclonus and respiratory depression need prompt assessment.','The choice of alternative drug and dose requires individualized conversion.'],'**Review pain, medicines, kidney function and reversible causes.**',['Seek specialist advice for complex rotation.','Do not use an equianalgesic table without allowing for clinical context and incomplete cross-tolerance.'],[['Risk','Accumulation/toxicity'],['Assessment','Sedation, breathing and pain'],['Plan','Individualized dose/rotation']],[OP],style='clinical_scenario')

q('A patient taking regular opioid analgesia has brief breakthrough cancer pain between scheduled doses. Which principle is most appropriate?', 'Provide an individualized immediate-release rescue plan and reassess the baseline regimen if episodes are frequent',[
 ('Use only an extra extended-release dose for each short episode','Extended-release preparations are generally unsuited to rapid episode relief.'),('Assume breakthrough pain means opioids can never work','The mechanism and regimen may need adjustment.'),('Prescribe the same rescue dose to every patient regardless of prior exposure','Rescue dosing depends on current opioid exposure, organ function and safety.')],
 'Baseline and episode pain require related but distinct plans','**A rapid, predictable rescue strategy can treat breakthrough episodes.**',['Frequent rescue use may indicate inadequate baseline control or a new complication.','Incident pain can require anticipatory planning.'],'**Review effectiveness and adverse effects after adjustment.**',['Provide clear instructions and limits for seeking help.','Assess for cord compression, fracture or another new cause when the pattern changes.'],[['Baseline','Regular analgesia'],['Breakthrough','Immediate-release rescue'],['Frequent episodes','Reassess cause and regimen']],[OP],style='clinical_scenario')

q('When starting regular opioid treatment for cancer pain, which bowel strategy is generally appropriate unless contraindicated?', 'Preventive laxative therapy, commonly using a stimulant and/or osmotic regimen tailored to the patient',[
 ('Wait for severe fecal impaction before considering prevention','Opioid constipation is predictable and should be anticipated.'),('Use bulk fiber alone despite poor intake and possible obstruction','Bulk agents can be unsuitable in this context.'),('Assume tolerance reliably develops to constipation as it does to some other effects','Constipation commonly persists.')],
 'Prevention should begin with the analgesic plan','**Opioids reduce gastrointestinal motility and secretion.**',['Assess baseline bowel function, intake and other constipating medicines.','Suspected obstruction requires a different assessment.'],'**Monitor stool frequency and symptoms and escalate appropriately.**',['Refractory opioid-induced constipation may warrant a peripheral opioid antagonist after contraindication review.','Do not overlook rectal loading or mechanical disease.'],[['Opioid effect','Reduced motility'],['Initial plan','Preventive laxative'],['Refractory symptoms','Reassess and consider targeted treatment']],[OP])

q('A patient on escalating opioids is difficult to rouse and has very slow breathing. Which immediate principle is correct?', 'Support ventilation and urgently treat suspected opioid toxicity, using titrated naloxone when indicated to restore adequate breathing',[
 ('Allow hypoventilation because opioids are prescribed for cancer','Prescribed use does not exclude life-threatening toxicity.'),('Use a large antagonist dose solely to eliminate all analgesia in every opioid-tolerant patient','Titration can restore ventilation while reducing severe withdrawal and pain.'),('Give another sedative before assessing the airway','This can worsen respiratory depression.')],
 'The physiological target is adequate ventilation','**Severe opioid toxicity is a medical emergency.**',['Call for assistance and manage airway and breathing.','Recurrent toxicity can occur when the opioid outlasts naloxone.'],'**Monitor closely and address the cause of accumulation or error.**',['Review renal function and co-sedatives.','Re-establish a safer pain plan after stabilization.'],[['Immediate threat','Hypoventilation'],['Rescue','Ventilation and indicated naloxone'],['Aftercare','Monitor recurrence and revise regimen']],[OP],style='clinical_scenario')

q('Burning, electric-shock pain with allodynia persists despite treatment of a tumor-related nerve lesion. Which analgesic strategy is reasonable?', 'Add an appropriate neuropathic-pain agent while continuing individualized multimodal cancer-pain care',[
 ('Use antibiotics as the specific treatment for every neuropathic symptom','Infection treatment is indicated only when infection is present.'),('Escalate an NSAID indefinitely without reviewing renal or gastrointestinal risk','This is neither targeted nor safe.'),('Assume neuropathic pain cannot coexist with nociceptive cancer pain','Mixed mechanisms are common.')],
 'Pain mechanism helps choose the adjunct','**Neuropathic pain arises from a lesion or disease of the somatosensory system.**',['Selected anticonvulsants or antidepressants may be useful.','Sedation, renal dosing, interactions and falls risk influence choice.'],'**Treat the structural cause when feasible and reassess function.**',['Consider radiotherapy or interventional input for selected lesions.','Monitor benefit rather than continuing an ineffective adjunct indefinitely.'],[['Features','Burning/shock/allodynia'],['Adjunct','Mechanism-directed agent'],['Assessment','Benefit and adverse effects']],[OP],style='clinical_scenario')

q('A patient has a painful uncomplicated bone metastasis without instability or cord compression. Which local treatment can provide meaningful symptom relief?', 'Palliative external-beam radiotherapy using an appropriate evidence-based fractionation schedule',[
 ('Emergency spinal decompression for every painful lesion regardless of anatomy','Surgery is selected for instability, compression and other indications.'),('Withholding all local treatment unless cure is possible','Local treatment can provide worthwhile palliation.'),('Giving a bone-modifying agent as the only possible pain treatment','Such agents do not replace all analgesic and local options.')],
 'Local control can be valuable without a curative endpoint','**Radiotherapy is effective for pain from many bone metastases.**',['Single- and multifraction schedules have defined roles.','Retreatment, prognosis, site and patient preference affect selection.'],'**Assess fracture and neurological risks before labeling the lesion uncomplicated.**',['Coordinate analgesia and rehabilitation.','Use orthopedic or spinal assessment when mechanical risk is present.'],[['Uncomplicated pain','Palliative RT option'],['Instability/fracture','Mechanical assessment'],['Cord compression','Emergency pathway']],[ref('ASTRO symptomatic bone metastases guideline','https://doi.org/10.1016/j.prro.2024.04.018')],style='clinical_scenario')

q('Before starting an oncological-dose bone-modifying agent, which preventive assessment is particularly relevant?', 'Dental assessment and management of avoidable oral infection or invasive dental needs when feasible',[
 ('A normal calcium result eliminates every jaw risk','Medication-related osteonecrosis of the jaw is a separate concern.'),('Routine extraction of every healthy tooth','Unnecessary invasive procedures are not the aim.'),('Dental symptoms need not be discussed during treatment','Early reporting and oral care remain important.')],
 'Prevention addresses a serious but avoidable component of risk','**Bisphosphonates and denosumab can be associated with jaw osteonecrosis.**',['Risk is affected by dose, exposure, oral disease and procedures.','Calcium, vitamin D and renal considerations vary by agent.'],'**Coordinate oncology and dental care before and during treatment.**',['Balance urgent cancer needs with dental preparation.','Explain symptoms that warrant review.'],[['Oral health','Pre-treatment assessment'],['Risk','Medication-related jaw osteonecrosis'],['Ongoing care','Hygiene and early symptom reporting']],[ref('MASCC/ISOO/ASCO jaw osteonecrosis guideline','https://doi.org/10.1200/JCO.19.01186')])

q('For a standard single-day highly emetogenic chemotherapy regimen, which prophylactic combination is recommended by MASCC/ESMO guidance?', 'A 5-HT3 antagonist, an NK1 antagonist, dexamethasone and olanzapine',[
 ('A 5-HT3 antagonist alone for every high-risk regimen','This is inadequate standard prophylaxis for highly emetogenic therapy.'),('Only an antihistamine and a proton-pump inhibitor','These do not provide the recommended pathway coverage.'),('Only an opioid antagonist and a laxative','These target other supportive-care issues.')],
 'Several emetic pathways require coverage','**A four-drug regimen is recommended for many standard highly emetogenic settings.**',['Acute and delayed phases require an appropriate schedule.','Sedation, interactions and regimen-specific steroid adjustments matter.'],'**Match prophylaxis to the actual regimen and patient risk.**',['Consider individual tolerability and contraindications.','Provide a clear breakthrough plan and reassess control each cycle.'],[['5-HT3/NK1 blockade','Complementary emetic pathways'],['Dexamethasone','Antiemetic component'],['Olanzapine','Additional nausea/vomiting control']],[NV])

q('A patient becomes nauseated on entering the chemotherapy unit before any drug is administered, after poorly controlled nausea during previous cycles. Which mechanism is most likely?', 'Conditioned anticipatory nausea',[
 ('Acute tumor lysis syndrome established by the location alone','That requires clinical and biochemical evidence.'),('An infusion reaction to a drug not yet administered','The timing argues against that immediate mechanism.'),('A proof that all symptoms are fabricated','Conditioned symptoms are real and can be distressing.')],
 'Prior uncontrolled symptoms can create a learned response','**Anticipatory nausea can be triggered by cues associated with treatment.**',['Good control from early cycles reduces risk.','Behavioral strategies and selected medicines may help.'],'**Improve subsequent prophylaxis and offer targeted supportive intervention.**',['Use relaxation, desensitization or other appropriate psychological techniques.','Continue to evaluate new symptoms for organic causes.'],[['Timing','Before administration'],['Trigger','Conditioned cues'],['Prevention','Effective early-cycle control']],[NV],style='clinical_scenario')

q('A patient receiving curative chemotherapy has anemia. Which statement about erythropoiesis-stimulating agents is correct?', 'They generally should not be offered for chemotherapy-associated anemia when treatment has curative intent',[
 ('They are preferred for every hemoglobin below 12 g/dL regardless of intent','Eligibility is more restricted and risks must be considered.'),('They have no thromboembolic risk','ESAs increase thromboembolic risk.'),('They immediately correct unstable symptomatic anemia as rapidly as transfusion','Their effect is delayed and they are not an emergency substitute for transfusion.')],
 'The cancer-treatment goal affects supportive-drug eligibility','**ASCO/ASH limits routine ESA consideration to appropriate noncurative chemotherapy-associated anemia contexts.**',['A hemoglobin below 10 g/dL is part of the relevant consideration, not an automatic indication.','Reversible causes of anemia require assessment.'],'**Use individualized transfusion and cause-directed treatment when appropriate.**',['Consider symptoms, bleeding, cardiovascular status and trajectory.','Do not generalize the ESA rule to every separate hematological indication.'],[['Curative chemotherapy','Generally no ESA'],['Selected noncurative setting','May consider with Hb below 10'],['Risks','Thrombosis and oncological concerns']],[ref('ASCO/ASH cancer-associated anemia ESA guideline','https://doi.org/10.1200/JCO.18.02142')])

q('When is primary G-CSF prophylaxis commonly recommended for a chemotherapy regimen?', 'When the overall febrile-neutropenia risk is approximately 20% or higher, with patient factors influencing decisions at intermediate risk',[
 ('For every anticancer drug irrespective of marrow risk','Prophylaxis is risk-based.'),('Only after a patient has already had multiple septic episodes','Primary prophylaxis aims to prevent a first event in an appropriate risk setting.'),('Only when the tumor is metastatic, never with curative treatment','It may help preserve a validated curative regimen when indicated.')],
 'Regimen and host risks are combined','**The risk estimate includes treatment intensity and patient-specific vulnerability.**',['Age, comorbidity, prior events and marrow status may influence intermediate-risk decisions.','Use the correct timing and preparation for the regimen.'],'**Distinguish prophylaxis from treatment of established febrile neutropenia.**',['G-CSF is not an automatic substitute for urgent antibiotics in fever.','Review whether an equally effective less myelotoxic regimen is appropriate.'],[['High overall risk','Primary prophylaxis generally appropriate'],['Intermediate risk','Host factors matter'],['Established fever','Urgent infection pathway']],[ref('ASCO white blood cell growth-factor guideline update 2026','https://doi.org/10.1200/JCO-25-02938')])
